sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    if (!chunk)
        return disposition;

    /* Increment relevant statistics for out-of-band chunk processing */
    net->sctp.stats.oob_chunks_received++;

    /* Validate chunk length */
    if (chunk->length < sizeof(sctp_chunkhdr_t)) {
        return SCTP_DISPOSITION_BAD;
    }

    switch (chunk->type) {
    case SCTP_SHUTDOWN_ACK:
        sctp_handle_shutdown_ack(net, ep, asoc, chunk, commands);
        disposition = SCTP_DISPOSITION_ABORT;
        break;
    case SCTP_COOKIE_ACK:
        sctp_handle_cookie_ack(net, ep, asoc, chunk, commands);
        disposition = SCTP_DISPOSITION_IGNORE;
        break;
    case SCTP_ERROR:
        if (sctp_handle_error(net, ep, asoc, chunk, commands))
            disposition = SCTP_DISPOSITION_ABORT;
        else
            disposition = SCTP_DISPOSITION_DROP;
        break;
    default:
        disposition = SCTP_DISPOSITION_DROP;
        break;
    }

    return disposition;
}

sctp_disposition_t process_sctp_chunk(struct net *net, const struct sctp_endpoint *ep,
                                      const struct sctp_association *asoc,
                                      sctp_subtype_t type, void *arg,
                                      sctp_cmd_seq_t *commands) {
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment appropriate SCTP statistics */
    net->sctp.stats.chunk_received[type]++;

    /* Validate chunk length */
    if (chunk->length < sizeof(sctp_chunk_t)) {
        return SCTP_DISPOSITION_DISCARD;
    }

    switch (type) {
        case SCTP_SUBTYPE_SHUTDOWN_ACK:
            /* Handle shutdown acknowledgment */
            sctp_shutdown_ack_handler(net, ep, asoc, chunk, commands);
            break;
        case SCTP_SUBTYPE_COOKIE_ACK:
            /* Handle cookie acknowledgment */
            sctp_cookie_ack_handler(net, ep, asoc, chunk, commands);
            break;
        case SCTP_SUBTYPE_ERROR:
            /* Handle error chunk */
            disposition = sctp_error_handler(net, ep, asoc, chunk, commands);
            break;
        default:
            /* Unknown or unsupported chunk type */
            disposition = SCTP_DISPOSITION_IGNORE;
            break;
    }

    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net, const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type, void *arg,
                                          sctp_cmd_seq_t *commands)
{
    struct sctp_chunk *chunk = arg;

    SCTP_INC_STATS(SctpInChunks);
    if (!sctp_chunk_length_valid(chunk, asoc)) {
        return SCTP_DISPOSITION_BAD;
    }

    switch (type) {
    case SCTP_SUBTYPE_SHUTDOWN_ACK:
        sctp_handle_shutdown_ack(net, ep, asoc, chunk, commands);
        break;
    case SCTP_SUBTYPE_COOKIE_ACK:
        sctp_handle_cookie_ack(net, ep, asoc, chunk, commands);
        break;
    case SCTP_SUBTYPE_ERROR:
        sctp_handle_error(net, ep, asoc, chunk, commands);
        break;
    default:
        return SCTP_DISPOSITION_CONSUME;
    }

    return SCTP_DISPOSITION_PROCESS;
}

sctp_disposition_t sctp_process_out_of_band_chunk(struct net *net,
                                                  const struct sctp_endpoint *ep,
                                                  const struct sctp_association *asoc,
                                                  sctp_subtype_t type,
                                                  void *arg,
                                                  sctp_cmd_seq_t *commands) {
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;

    if (!chunk) {
        return SCTP_DISPOSITION_NOMEM;
    }

    if (chunk->chunk_hdr->type != type) {
        return SCTP_DISPOSITION_BAD;
    }

    if (!sctp_chunk_length_valid(chunk)) {
        return SCTP_DISPOSITION_BAD;
    }

    switch (type) {
    case SCTP_SUBTYPE_SHUTDOWN_ACK:
        sctp_process_shutdown_ack(net, ep, asoc, chunk, commands);
        break;
    case SCTP_SUBTYPE_COOKIE_ACK:
        sctp_process_cookie_ack(net, ep, asoc, chunk, commands);
        break;
    case SCTP_SUBTYPE_ERROR:
        sctp_process_error(net, ep, asoc, chunk, commands);
        break;
    default:
        return SCTP_DISPOSITION_UNKNOWN;
    }

    net->sctp_stats->chunks_processed++;
    return SCTP_DISPOSITION_CONSUME;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    struct sctp_chunkhdr *chunk = arg;

    if (!chunk || ntohs(chunk->length) < sizeof(*chunk))
        return SCTP_DISPOSITION_BAD;

    switch (type) {
    case SCTP_SUBTYPE_SHUTDOWN_ACK:
        sctp_add_cmd(commands, SCTP_CMD_SHUTDOWN_ACK, NULL);
        break;
    case SCTP_SUBTYPE_COOKIE_ECHO:
        sctp_add_cmd(commands, SCTP_CMD_COOKIE_ECHO, NULL);
        break;
    case SCTP_SUBTYPE_ERROR:
        sctp_add_cmd(commands, SCTP_CMD_REPORT_ERROR, arg);
        break;
    default:
        disposition = SCTP_DISPOSITION_IGNORE;
        break;
    }

    return disposition;
}
